reference.cpp:
#include <cstdio>
#include <vector>
#include <string>
#include <queue>
#include <iostream>

struct Node {
    long long v;
    Node *l = nullptr, *r = nullptr;
};

Node* buildTree(const std::vector<std::string> &t) {
    if (t.empty() || t[0] == "null") return nullptr;
    Node *root = new Node{std::stoll(t[0])};
    std::queue<Node*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < t.size()) {
        Node *cur = q.front(); q.pop();
        if (i < t.size()) {
            if (t[i] != "null") { cur->l = new Node{std::stoll(t[i])}; q.push(cur->l); }
            ++i;
        }
        if (i < t.size()) {
            if (t[i] != "null") { cur->r = new Node{std::stoll(t[i])}; q.push(cur->r); }
            ++i;
        }
    }
    return root;
}

Node* invert(Node *n) {
    if (!n) return nullptr;
    std::swap(n->l, n->r);
    invert(n->l);
    invert(n->r);
    return n;
}

int main() {
    std::vector<std::string> tok;
    std::string t;
    while (std::cin >> t) tok.push_back(t);
    if (tok.empty()) tok.push_back("null");

    Node *root = invert(buildTree(tok));

    if (!root) { printf("null\n"); return 0; }   // 空树单独处理

    // 层序输出，末尾 null 省略
    std::vector<std::string> out;
    std::queue<Node*> q;
    q.push(root);
    while (!q.empty()) {
        Node *n = q.front(); q.pop();
        if (!n) { out.push_back("null"); continue; }
        out.push_back(std::to_string(n->v));
        q.push(n->l);
        q.push(n->r);
    }
    while (!out.empty() && out.back() == "null") out.pop_back();
    for (size_t i = 0; i < out.size(); ++i) {
        if (i) printf(" ");
        printf("%s", out[i].c_str());
    }
    printf("\n");
    return 0;
}
